export type CheckoutSession = { "active_payment_attempt"?: OrderPaymentAttempt; /** Contact the buyer entered in checkout before paying, saved with the session's checkout credential. Omitted until the buyer saves or clears a field. When a checkout session payment omits buyer_contact.email or buyer_contact.phone, Flint uses these values. Flint clears the contact 30 days after the session ends, and when a customer linked to the session is deleted. */ "buyer_contact"?: CheckoutBuyerContact; "checkout_session_id": string; /** The note supplied when the checkout session was closed. It is not shown to the buyer. */ "closed_reason"?: string; /** RFC3339 timestamp. Format: date-time. */ "created_at"?: string; "custom_text"?: CheckoutCustomTextWriteConfig; "customer"?: (({ /** RFC3339 timestamp. Format: date-time. */ "created_at"?: string; "customer_id": string; "email": string; "name"?: string; "phone"?: string; /** RFC3339 timestamp. Format: date-time. */ "updated_at"?: string; }) | (null)); "customer_collection"?: CheckoutCustomerConfig; /** Contact and default addresses of the customer the checkout acts for, with the recipient name on its default shipping address: the customer the merchant created the session for, or the customer whose email the buyer confirmed in it. Present only on reads with the session's checkout credential while the session is open and acts for a customer. */ "customer_prefill"?: CheckoutCustomerPrefill; /** Immutable delivery method assignment captured when the checkout was created. */ "delivery_method_ids": Array<string>; /** Merchant-only immutable configuration lineage used to evaluate delivery quotes. */ "delivery_pinned_dependencies"?: Array<CheckoutDeliveryPinnedDependency>; /** Whether the order has at least one remaining quote-resolved fulfillment choice that must be selected before payment. */ "delivery_selection_required": boolean; "expiration"?: CheckoutExpirationConfig; /** RFC3339 timestamp. Format: date-time. */ "expires_at"?: string; /** Caller-owned identifier for this resource in an external system. maxLength: 255. */ "external_reference_id"?: string; /** Current fulfillment choices for Flint-owned pricing. Checkout credentials receive the fields available to buyers; merchant credentials also receive configuration lineage and diagnostics. External pricing reports requires_explicit_quote; reading this field does not request a delivery quote. Omitted when the session is not open, has no order, or Flint cannot read its delivery. */ "fulfillment"?: (({ "choice_groups": Array<DeliveryQuoteChoiceGroupResource>; "delivery_quote_id"?: string; "evaluation_status": "complete" | "incomplete" | "degraded" | "requires_explicit_quote" | (string & {}); /** RFC3339 timestamp. Format: date-time. */ "expires_at"?: string; /** Inputs the checkout's delivery methods need. Once the checkout has a delivery quote, these are the quote's input_requirements. Before that, they come from the methods alone and name no choice group: the fields in each method's quote_input_fields, and each recipient field a method requires. */ "input_requirements": Array<DeliveryInputRequirement>; "merchant_diagnostics": Array<DeliveryMerchantDiagnostic>; }) | ({ "buyer_reasons": Array<string>; "choice_groups": Array<BuyerDeliveryQuoteChoiceGroupResource>; "delivery_quote_id"?: string; "evaluation_status": "complete" | "incomplete" | "degraded" | "requires_explicit_quote" | (string & {}); /** RFC3339 timestamp. Format: date-time. */ "expires_at"?: string; /** Inputs the checkout's delivery methods need. Once the checkout has a delivery quote, these are the quote's input_requirements. Before that, they come from the methods alone and name no choice group: the fields in each method's quote_input_fields, and each recipient field a method requires. */ "input_requirements": Array<BuyerDeliveryInputRequirementResource>; }) | (object)); "invoice"?: (({ "collection_block_status"?: "none" | "inventory_blocked" | "resolved" | (string & {}); /** RFC3339 timestamp. Format: date-time. */ "created_at"?: string; "customer_id"?: string; /** RFC3339 timestamp. Format: date-time. */ "due_at"?: string; "invoice_id": string; "invoice_number"?: string; "is_overdue": boolean; "order_id"?: string; "outstanding_money": MoneyValue; "paid_money": MoneyValue; "refund_status"?: "none" | "partially_refunded" | "refunded" | (string & {}); "refunded_money": MoneyValue; "status": "draft" | "open" | "partially_paid" | "paid" | "void" | "uncollectible" | "credited" | (string & {}); /** RFC3339 timestamp. Format: date-time. */ "updated_at"?: string; }) | (null)); "invoice_id"?: string; "legal"?: LegalSettings; "merchant_id"?: string; /** How the buyer can reach the merchant for help: the support email, phone, and URL the merchant set. Present only on reads with the session's checkout credential, and only when the merchant set at least one of them. Show it where your checkout tells the buyer to contact the merchant, such as an expired or closed checkout, or your receipt. */ "merchant_support"?: CheckoutMerchantSupport; "metadata"?: Record<string, string>; "order"?: (({ /** RFC3339 timestamp. Format: date-time. */ "created_at"?: string; "customer_id"?: string; "fulfillment_status"?: "not_fulfilled" | "partially_fulfilled" | "fulfilled" | "canceled" | "not_applicable" | "closed" | (string & {}); "order_id": string; "order_number"?: string; "payment_intent_ids"?: Array<string>; "payment_status": "unpaid" | "partially_paid" | "paid" | (string & {}); "pricing_amounts": PricingAmounts; "refund_status": "none" | "partially_refunded" | "refunded" | (string & {}); "settlement_amounts": SettlementAmounts; "status": "open" | "closed" | (string & {}); /** RFC3339 timestamp. Format: date-time. */ "updated_at"?: string; }) | (null)); "order_id"?: string; "origin"?: "virtual_terminal" | "payment_link" | "checkout" | "api" | "subscription" | (string & {}); "payment_collection"?: PaymentCollection; "payment_intent_ids"?: Array<string>; "payment_intents"?: Array<ExpandedPaymentIntentSummary>; "payment_link"?: (({ /** Format: int32. */ "completed_count": number; /** RFC3339 timestamp. Format: date-time. */ "created_at"?: string; "description"?: string; "name": string; "payment_link_id": string; "payment_link_type"?: "standard" | "donation" | "event" | (string & {}); "status": "active" | "inactive" | (string & {}); "subscription_plan_id"?: string; /** RFC3339 timestamp. Format: date-time. */ "updated_at"?: string; "url"?: string; }) | (null)); "payment_link_id"?: string; /** The card the buyer saved with this checkout's payment by giving a mobile phone number, and whether they confirmed it. Present only on reads with the session's checkout credential, after a payment that paid the order in full, or that was approved for the merchant to capture later, and saved a card this way. A checkout whose payment is approved stays open until the capture. */ "payment_method_save"?: CheckoutPaymentMethodSave; "payments"?: CheckoutPaymentConfig; /** Named conditions that affect checkout completion. Follow each problem's remediation action instead of reconstructing delivery lifecycle rules in the client. When Flint cannot read the checkout's delivery, the read still succeeds and reports delivery_selection_stale; its remediation says whether reading the session again can succeed, and its next action's reason_code names the error. */ "problems": Array<CheckoutProblemResource>; "promotion_config"?: CheckoutPromotionConfig; /** RFC3339 deadline for the restricted payment-attempt recovery window. Format: date-time. */ "recovery_expires_at"?: string | null; /** Whether this terminal session credential is temporarily restricted to recovering its owning payment attempt. */ "recovery_mode": boolean; /** Payment attempt that this checkout credential may recover while recovery_mode is true. */ "recovery_payment_attempt_id"?: string; "redirects"?: CheckoutRedirectsConfig; /** Whether checkout offers the buyer the option to save the card they type for faster checkout at this merchant. Present only on reads with the session's checkout credential. When true and save_payment_method_requires_verification is false, PayOrder accepts save_payment_method: true for one newly collected card. False when the merchant turned checkout.saved_payment_details off, customer accounts are merchant hosted, card is not an available payment option, the checkout collects an invoice, a subscription, or a return, or the checkout acts for no customer and Flint cannot email the buyer a verification code. */ "save_payment_method_offered"?: boolean; /** Whether the buyer can save the card they type by giving a US or Canadian mobile phone number with the payment, in save_payment_method_phone on POST /v1/orders/{order_id}/pay, and confirming it with a texted code after paying. Present only on reads with the session's checkout credential. True while Flint can send texts and either save_payment_method_requires_verification is true, so the number replaces confirming an email before paying, or the checkout acts for the customer whose email the buyer confirmed with this credential, so the number joins that customer's saved details once the buyer confirms it. */ "save_payment_method_phone_offered"?: boolean; /** Whether the buyer must confirm their email with a code before the checkout can save their card or use their saved cards. Present only on reads with the session's checkout credential. True when save_payment_method_offered is true and the checkout acts for no customer for this credential: the merchant created it without one, and either the buyer has not confirmed an email with this credential, or the customer whose email they confirmed has since changed that email or been deleted. A credential other than the one a confirmation returned, such as the hosted checkout link opened on another device, reads true. Send the code with POST /v1/checkout-sessions/{checkout_session_id}/customer-verifications. False while the checkout acts for a customer, and whenever save_payment_method_offered is false. */ "save_payment_method_requires_verification"?: boolean; "setup_collection"?: PaymentCollection; "status": "open" | "paid" | "partially_paid" | "expired" | "closed" | "invalidated" | (string & {}); "subscription_plan_id"?: string; /** Renewal terms a subscription checkout commits the buyer to. Frozen when the session's order was created, so later plan changes do not alter them. Absent when the checkout starts no subscription. */ "subscription_terms"?: CheckoutSubscriptionTerms; "superseding_checkout_session_id"?: string; "surface": "hosted" | "embedded" | (string & {}); "tax"?: CheckoutTaxConfig; "terminal_reason"?: "payment_succeeded" | "payment_partially_succeeded" | "expired" | "api" | "order_mutated" | "superseded" | "invoice_paid_elsewhere" | "invoice_voided" | "invoice_uncollectible" | "invoice_balance_changed" | (string & {}); "theme"?: ThemeConfig; "tip"?: CheckoutTipConfig; /** RFC3339 timestamp. Format: date-time. */ "updated_at"?: string; /** Hosted checkout URL that carries a one-time launch credential. Send the buyer here to pay. Returned for a hosted session on every launch result: create, payment-link resolve, and invoice and return-resolution checkout. Reads return it only to a credential that can manage checkout sessions. Omitted for embedded sessions. */ "url"?: string; };
